<script setup lang="ts">import{onBeforeUnmount,onMounted,ref,watch}from"vue";import*as echarts from"echarts";const p=defineProps<{labels:string[];values:number[];compare?:number[]}>();const el=ref<HTMLElement>();let chart:echarts.ECharts|undefined,observer:ResizeObserver|undefined;const draw=()=>{if(!chart)return;const series=[{name:'学生能力',value:p.values}];if(p.compare)series.push({name:'岗位要求',value:p.compare});chart.setOption({tooltip:{},legend:{bottom:0,textStyle:{color:'#64748b'}},radar:{radius:'62%',center:['50%','46%'],indicator:p.labels.map(name=>({name,max:100})),splitNumber:4,axisName:{color:'#475569'},splitArea:{areaStyle:{color:['#fff','#f8fafc']}},axisLine:{lineStyle:{color:'#dbe4ef'}},splitLine:{lineStyle:{color:'#dbe4ef'}}},series:[{type:'radar',data:series,symbolSize:5,lineStyle:{width:2},areaStyle:{opacity:.12}}]})};onMounted(()=>{chart=echarts.init(el.value!);draw();observer=new ResizeObserver(()=>chart?.resize());observer.observe(el.value!)});watch(()=>[p.labels,p.values,p.compare],draw,{deep:true});onBeforeUnmount(()=>{observer?.disconnect();chart?.dispose()});</script><template><div ref="el" class="chart-canvas"/></template>
